local function extgui()
if G.zg2 then
for _,o in ipairs(G.zg2) do pcall(function() o:Destroy() end) end
G.zg2=nil
end
G.extMapped={}
local holders,own={},{}
local okS,sp=pcall(function() return script end)
if okS and typeof(sp)=="Instance" and sp.Parent and sp.Parent:IsA("ScreenGui") and sp.Parent.Name~="64DudeControls" then
holders[1]=sp.Parent
else
local okG,obj=pcall(function() return game:GetObjects("rbxassetid://"..EXT)[1] end)
if not okG or not obj then say("custom GUI could not be loaded, using the built-in one",true) return end
if obj:IsA("LuaSourceContainer") then return end
if obj:IsA("ScreenGui") then holders[1]=obj
else
for _,d in ipairs(obj:GetDescendants()) do
if d:IsA("ScreenGui") then holders[#holders+1]=d end
end
if #holders==0 then
local h=Instance.new("ScreenGui")
h.IgnoreGuiInset=true
if obj:IsA("GuiObject") then obj.Parent=h
else
for _,c in ipairs(obj:GetChildren()) do if c:IsA("GuiObject") then c.Parent=h end end
end
holders[1]=h
end
end
for _,h in ipairs(holders) do own[#own+1]=h end
end
local KEYS={jump={"jump"},punch={"punch","kick","attack","hit"},crouch={"crouch","pound","duck"},emote={"emote","dance","wave","taunt"}}
local TOK={jump="a",punch="b",crouch="z"}
local map,cnt,found={},0,{}
for _,holder in ipairs(holders) do
for _,d in ipairs(holder:GetDescendants()) do
if d:IsA("GuiButton") then
if #found<10 then found[#found+1]=d.Name end
local txt=string.lower(d.Name)
local tok={string.lower(d.Name)}
pcall(function() txt=txt.." "..string.lower(d.Text) tok[#tok+1]=string.lower(d.Text) end)
for _,c in ipairs(d:GetChildren()) do
if c:IsA("TextLabel") then txt=txt.." "..string.lower(c.Text) tok[#tok+1]=string.lower(c.Text) end
end
for k,ws in pairs(KEYS) do
if not map[k] then
for _,w in ipairs(ws) do
if string.find(txt,w,1,true) then map[k]=d cnt=cnt+1 break end
end
end
end
for k,w in pairs(TOK) do
if not map[k] then
for _,t in ipairs(tok) do
if t==w then map[k]=d cnt=cnt+1 break end
end
end
end
end
end
end
if cnt<2 then
for _,o in ipairs(own) do pcall(function() o:Destroy() end) end
say("custom GUI buttons not recognised ("..(#found>0 and table.concat(found,", ") or "none found").."), using the built-in one",true)
return
end
