names[#names+1]=k
end
for _,k in ipairs({"jump","punch","crouch","emote"}) do
if map[k] then B[k].fr.Visible=false G.extMapped[k]=true end
end
say("custom GUI loaded, buttons: "..table.concat(names,", "),true)
end
