local function makeVisual(ch,hum,root)
local V={}
local S=MH/2.355
local tex
local okT,eT=pcall(texture)
if okT then tex=eT else say("texture failed (enable Mesh/Image APIs): "..tostring(eT),true) end
local model=Instance.new("Model")
model.Name="Mario64"
model.Parent=ch
local byBone={}
for _,p in ipairs(_M.MESH_PARTS) do byBone[p.bone]=p end
local piece,center={},{}
local failed=false
for _,name in ipairs(ROT) do
local p=byBone[name]
local part
if p then
local ok,res=pcall(mesh,p,S,tex)
if ok then part=res
else
if not failed then failed=true say("mesh failed, using blocks: "..tostring(res),true) end
part=Instance.new("Part")
part.Size=p.size*S
part.Material=Enum.Material.SmoothPlastic
local key=name:match("Head") or name:match("Hand") or name:match("Shoe") or name:match("Forearm") or name:match("Arm") or name:match("Thigh") or name:match("Leg") or name
part.Color=COL[key] or Color3.new(1,1,1)
end
center[name]=p.c*S
else
part=Instance.new("Part")
part.Size=Vector3.new(0.2,0.2,0.2)
part.Transparency=1
center[name]=Vector3.zero
end
part.Name="M64_"..name
part.Anchored=false
part.CanCollide=false
part.CanQuery=false
part.CanTouch=false
part.Massless=true
part.Parent=model
piece[name]=part
end
local feet=root.Size.Y/2+hum.HipHeight
local bodyC0=CFrame.new(0,-feet+0.114*S-LOWER*MH/5,0)*CFrame.Angles(0,FACE,0)
local motors,baseC0,nodeT={},{},{}
for j,name in ipairs(ROT) do
local m=Instance.new("Motor6D")
m.Name="M64_"..name
if name=="Body" then
m.Part0=root
m.C0=bodyC0
m.C1=CFrame.new(-center[name])
else
local par=PARENT[name]
m.Part0=piece[par]
m.C0=CFrame.new(-center[par])
m.C1=CFrame.new(-center[name])
end
m.Part1=piece[name]
m.Parent=piece[name]
motors[j]=m
baseC0[j]=m.C0
nodeT[j]=(_M.NODE_T[name] or Vector3.zero)*S
end
local function hide()
for _,d in ipairs(ch:GetDescendants()) do
if not d:IsDescendantOf(model) then
if d:IsA("BasePart") and d~=root then d.Transparency=1
elseif d:IsA("Decal") or d:IsA("Texture") then d.Transparency=1 end
end
end
end
pcall(function() hum:RemoveAccessories() end)
hide()
task.spawn(function()
while model.Parent and hum.Health>0 do
pcall(hide)
task.wait(0.25)
end
end)
local st={name=nil,data=nil,t=0,spd=1,tgt=1,loop=false,lo=0,hi=0}
local kA,kB={},{}
local pA,pB={X=0,Y=0,Z=0},{X=0,Y=0,Z=0}
local lastPose,lastPos=nil,Vector3.zero
local blendFrom,blendFromPos,blendT,blendDur=nil,nil,1,0.1
local function play(name,speed)
if st.name==name then st.tgt=speed return end
local hex=MAP[name]
local data=hex and getAnim(hex)
if not data then return end
if lastPose then
blendFrom=table.clone(lastPose)
blendFromPos=lastPos
blendT=0
blendDur=0.12
end
st.name=name
if V.onPlay then pcall(V.onPlay,name) end
st.data=data
st.t=0
st.spd=speed
st.tgt=speed
st.loop=LOOPED[name]==true
local seg=SEG[name]
st.lo=seg and seg[1] or 0
st.hi=seg and seg[2] or (data.n-1)
end
local function done()
return st.data and not st.loop and st.lo+st.t*30>=st.hi-0.01
end
local function pose(dt)
local a=st.data
if not a then return end
st.spd=st.spd+(st.tgt-st.spd)*math.min(1,dt*10)
st.t=st.t+dt*st.spd
local last=a.n-1
local function evalAt(f,ps)
local k0=math.min(math.floor(f/a.step),a.keys-1)
local k1=math.min(k0+1,a.keys-1)
local t0=math.min(k0*a.step,last)
local t1=math.min(k1*a.step,last)
local al=(t1>t0) and math.clamp((f-t0)/(t1-t0),0,1) or 0
sample(a,k0,kA,pA)
sample(a,k1,kB,pB)
for j=1,#ROT do ps[j]=kA[j]:Lerp(kB[j],al) end
return Vector3.new(pA.X+(pB.X-pA.X)*al,pA.Y+(pB.Y-pA.Y)*al,pA.Z+(pB.Z-pA.Z)*al)*S
end
local ps,pos={},nil
local xf=st.loop and XF[st.name]
if xf and not SEG[st.name] and a.n>xf*2 then
local L=a.n-xf
local f=(st.t*30)%L
pos=evalAt(f,ps)
if f<xf then
local ps2={}
local pos2=evalAt(L+f,ps2)
local w=f/xf
for j=1,#ROT do ps[j]=ps2[j]:Lerp(ps[j],w) end
pos=pos2:Lerp(pos,w)
end
else
local f
if st.loop then f=st.lo+(st.t*30)%math.max(st.hi-st.lo,1) else f=math.min(st.lo+st.t*30,st.hi) end
pos=evalAt(f,ps)
end
lastPose=table.clone(ps)
lastPos=pos
if blendFrom and blendT<1 then
blendT=blendT+dt/blendDur
local w=math.clamp(blendT,0,1)
for j=1,#ROT do ps[j]=blendFrom[j]:Lerp(ps[j],w) end
pos=blendFromPos:Lerp(pos,w)
if blendT>=1 then blendFrom=nil end
end
for j=1,#ROT do
local cf
if j==1 then cf=CFrame.new(pos)*ps[j] else cf=CFrame.new(nodeT[j])*ps[j] end
motors[j].C0=baseC0[j]*cf
end
end
V.S=S V.tex=tex V.model=model V.piece=piece V.center=center V.motors=motors V.baseC0=baseC0 V.nodeT=nodeT V.st=st V.play=play V.pose=pose V.done=done V.feet=feet V.hide=hide
return V
end
