local function tryGrab(fwd,U)
if G.nograb then return false end
local center=root.Position+fwd*(3.4*U)+Vector3.new(0,-0.2*U,0)
local lim=(G.grabany and 100 or 16)*U
local best,bm,bd=nil,nil,1e9
for _,p in ipairs(boxParts(center,Vector3.new(8*U,6*U,8*U))) do
if p:IsA("BasePart") and not p:IsA("Terrain") then
local m=charOf(p)
local t=p
if m then t=m:FindFirstChild("HumanoidRootPart") end
if t and t:IsA("BasePart") and (m or not t.Anchored or G.grabany) and math.max(t.Size.X,t.Size.Y,t.Size.Z)<=lim and (m or t.Transparency<1) then
local d=(t.Position-center).Magnitude
if d<bd then best,bm,bd=t,m,d end
end
end
end
if not best then return false end
local cc={}
local list={best}
if bm then list=bm:GetDescendants() else pcall(function() list=best:GetConnectedParts(true) end) end
for _,q in ipairs(list) do
if q:IsA("BasePart") then
cc[q]=q.CanCollide
q.CanCollide=false
if q.Anchored and not bm then q.Anchored=false end
end
end
held={part=best,model=bm,cc=cc}
return true
end
local function release(throw,fwd)
