local p=h.part
if not p.Parent or not p:IsDescendantOf(workspace) then release(false,fwd) return end
local sz=p.Size
local ext=math.max(sz.X,sz.Z)*0.5
local pos=root.Position+fwd*(1.3*U+ext)+Vector3.new(0,0.55*U+sz.Y*0.3,0)
local rot=h.model and CFrame.lookAt(Vector3.zero,fwd) or p.CFrame.Rotation
p.CFrame=CFrame.new(pos)*rot
