local function camfx()
pcall(function() RS:UnbindFromRenderStep("64DudeCamA") end)
pcall(function() RS:UnbindFromRenderStep("64DudeCam") end)
if G.cin then G.cin:Disconnect() end
local T,D
local ax,ay=0,0
G.cin=UIS.InputChanged:Connect(function(i,gp)
if gp or i.UserInputType~=Enum.UserInputType.Touch then return end
ax=ax+i.Delta.X
ay=ay+i.Delta.Y
end)
RS:BindToRenderStep("64DudeCamA",Enum.RenderPriority.Camera.Value-1,function()
if G.camOn==false then return end
local cam=workspace.CurrentCamera
if not T or not cam then return end
local cf=T
if ax~=0 or ay~=0 then
local l=cf.LookVector
local yaw=math.atan2(-l.X,-l.Z)-ax*0.0141*(SENS-1)
local pit=math.clamp(math.asin(l.Y)-ay*0.0106*(SENS-1),-1.3,1.3)
cf=CFrame.new(cf.Position)*CFrame.Angles(0,yaw,0)*CFrame.Angles(pit,0,0)
ax,ay=0,0
end
cam.CFrame=cf
end)
RS:BindToRenderStep("64DudeCam",Enum.RenderPriority.Camera.Value+1,function(dt)
if G.camOn==false then D=nil T=nil return end
local cam=workspace.CurrentCamera
if not cam then return end
local t=cam.CFrame
T=t
if not D or (D.Position-t.Position).Magnitude>30 then D=t return end
dt=math.min(dt,0.05)
local p=D.Position:Lerp(t.Position,1-math.exp(-dt*CAMPOS))
local r=D.Rotation:Lerp(t.Rotation,1-math.exp(-dt*CAMROT))
D=CFrame.new(p)*r
cam.CFrame=D
end)
end
