local function bb(l)
local lo,hi=Vector3.new(1e9,1e9,1e9),Vector3.new(-1e9,-1e9,-1e9)
for _,p in ipairs(l) do
local cf,z=p.CFrame,p.Size/2
for x=-1,1,2 do for y=-1,1,2 do for q=-1,1,2 do
local v=(cf*CFrame.new(z.X*x,z.Y*y,z.Z*q)).Position
lo=Vector3.new(math.min(lo.X,v.X),math.min(lo.Y,v.Y),math.min(lo.Z,v.Z))
hi=Vector3.new(math.max(hi.X,v.X),math.max(hi.Y,v.Y),math.max(hi.Z,v.Z))
end end end
end
return lo,hi
end
local function skin(vis,m)
local rp=m:FindFirstChild("RootPart",true) or m.PrimaryPart
local rc=rp and rp.CFrame.Rotation or CFrame.new()
for _,d in ipairs(m:GetDescendants()) do
if d:IsA("JointInstance") or d:IsA("WeldConstraint") or d:IsA("Constraint") or d:IsA("LuaSourceContainer") or d:IsA("Humanoid") or d:IsA("AnimationController") then d:Destroy() end
end
local mp={}
for _,d in ipairs(m:GetDescendants()) do
if d:IsA("BasePart") then
if d.Transparency>=1 then d:Destroy()
else
d.Anchored=true d.CanCollide=false d.CanTouch=false d.CanQuery=false d.Massless=true
mp[#mp+1]=d
end
end
end
local vr=vis:FindFirstChild("HumanoidRootPart")
local rl={}
for _,n in ipairs(PARTS) do
local q=vis:FindFirstChild(n)
if q and q:IsA("BasePart") then rl[#rl+1]=q end
end
if #mp==0 or not vr or #rl==0 then return false end
local dl=vr.CFrame.Rotation*CFrame.Angles(0,YAW,0)*rc:Inverse()
for _,p in ipairs(mp) do p.CFrame=dl*p.CFrame end
local vlo,vhi=bb(rl)
local mlo,mhi=bb(mp)
local f=(vhi.Y-vlo.Y)/math.max(mhi.Y-mlo.Y,0.01)*MFIT
pcall(function() m:ScaleTo(f) end)
mlo,mhi=bb(mp)
local sh=Vector3.new((vlo.X+vhi.X)/2-(mlo.X+mhi.X)/2,vlo.Y-mlo.Y,(vlo.Z+vhi.Z)/2-(mlo.Z+mhi.Z)/2)
for _,p in ipairs(mp) do p.CFrame=p.CFrame+sh end
local mcx=(mlo.X+mhi.X)/2+sh.X
local vcx,vcz=(vlo.X+vhi.X)/2,(vlo.Z+vhi.Z)/2
local sx=(vhi.X-vlo.X)/math.max(mhi.X-mlo.X,0.01)
local sy=(vhi.Y-vlo.Y)/math.max(mhi.Y-mlo.Y,0.01)
for _,p in ipairs(mp) do
local c=p.Position
local u=Vector3.new(vcx+(c.X-mcx)*sx,vlo.Y+(c.Y-(mlo.Y+sh.Y))*sy,vcz)
local best,bd
for _,q in ipairs(rl) do
local l=q.CFrame:PointToObjectSpace(u)
local z=q.Size/2
local d=Vector3.new(math.max(math.abs(l.X)-z.X,0),math.max(math.abs(l.Y)-z.Y,0),math.max(math.abs(l.Z)-z.Z,0)).Magnitude
if not bd or d<bd then best,bd=q,d end
end
local w=Instance.new("Weld")
w.Part0=best
w.Part1=p
w.C0=best.CFrame:ToObjectSpace(p.CFrame)
w.Parent=p
p.Anchored=false
end
for _,q in ipairs(rl) do q.Transparency=1 end
for _,d in ipairs(vis:GetDescendants()) do
if d:IsA("Decal") then d.Transparency=1 end
end
m.Parent=vis
return true
end
local function rig(ch,sm,hum)
local rr=ch:FindFirstChild("HumanoidRootPart")
local mp={}
for _,d in ipairs(sm:GetDescendants()) do
if d:IsA("LuaSourceContainer") or d:IsA("Humanoid") then d:Destroy()
elseif d:IsA("BasePart") then
d.Anchored=false d.CanCollide=false d.CanTouch=false d.CanQuery=false d.Massless=true
mp[#mp+1]=d
end
end
local vr=sm:FindFirstChild("RootPart",true) or sm.PrimaryPart or mp[1]
if not vr or not rr then return end
sm.Name="64DudeVisual"
sm.Parent=ch
local lo,hi=bb(mp)
pcall(function() sm:ScaleTo(sm:GetScale()*5*SCALE*MFIT/math.max(hi.Y-lo.Y,0.01)) end)
lo,hi=bb(mp)
local rot=CFrame.Angles(0,RYAW,0)*vr.CFrame.Rotation
local off=(vr.Position.Y-lo.Y)-(hum.HipHeight+rr.Size.Y/2)
vr.CFrame=rr.CFrame*CFrame.new(0,off,0)*rot
local w=Instance.new("Weld")
w.Part0=rr
w.Part1=vr
w.C0=CFrame.new(0,off,0)*rot
w.Parent=vr
return sm,w
end
local function kfs(all)
local KS=game:GetService("KeyframeSequenceProvider")
local AL={idle={"idle","stand","wait"},walk={"walk","slow"},run={"run","sprint"},jump={"jump"},fall={"fall","air"},climb={"climb"},swim={"swim"}}
local own,seen,sc={},{},{}
for _,a in ipairs(all) do
if a:IsA("KeyframeSequence") then
local ok,id=pcall(function() return KS:RegisterKeyframeSequence(a) end)
if ok and id then
seen[#seen+1]=a.Name
local n=a.Name:lower()
for _,k in ipairs(KEYS) do
local hit
for _,wd in ipairs(AL[k]) do if n:find(wd,1,true) then hit=true end end
if hit then
if not own[k] or #n<sc[k] then
local an=Instance.new("Animation")
an.AnimationId=id
own[k]=an
sc[k]=#n
end
break
end
end
end
end
end
return own,seen
end
local function visual(ch,d,sh,pre)
local function mk() return pcall(function() return P:CreateHumanoidModelFromDescription(d,Enum.HumanoidRigType.R15) end) end
local ok,m=mk()
if (not ok or not m) and sh then d.Head=sh ok,m=mk() end
if not ok or not m then say("outfit model failed: "..tostring(m),true) return end
m.Name="64DudeVisual"
local h=m:FindFirstChildOfClass("Humanoid")
if h then
for k,v in pairs({EvaluateStateMachine=false,WalkSpeed=0,RequiresNeck=false,BreakJointsOnDeath=false,DisplayDistanceType=Enum.HumanoidDisplayDistanceType.None,HealthDisplayType=Enum.HumanoidHealthDisplayType.AlwaysOff}) do
pcall(function() h[k]=v end)
end
end
for _,x in ipairs(m:GetDescendants()) do
if x:IsA("LuaSourceContainer") then x:Destroy()
elseif x:IsA("BasePart") then x.Anchored=false x.CanCollide=false x.CanTouch=false x.CanQuery=false x.Massless=true end
end
m.Parent=ch
local rr,vr=ch:FindFirstChild("HumanoidRootPart"),m:FindFirstChild("HumanoidRootPart")
if not rr or not vr then m:Destroy() return end
if pre then pre(m) end
pcall(function() m:ScaleTo(SCALE) end)
local hh=ch:FindFirstChildOfClass("Humanoid")
local y0=fb(m)
local off=LIFT
if y0 and hh then off=off+(vr.Position.Y-y0)-(hh.HipHeight+rr.Size.Y/2) end
vr.CFrame=rr.CFrame*CFrame.new(0,off,0)
vr.Transparency=1
local w=Instance.new("Weld")
w.Part0=rr
w.Part1=vr
w.C0=CFrame.new(0,off,0)
w.Parent=vr
for _,n in ipairs(PARTS) do
local v=m:FindFirstChild(n)
if v and v:IsA("BasePart") then v.Color=SKIN end
end
return m,w
end
local function hide(ch)
for _,n in ipairs(PARTS) do
local p=ch:FindFirstChild(n)
if p and p:IsA("BasePart") then
p.Transparency=1
p:GetPropertyChangedSignal("Transparency"):Connect(function()
if p.Transparency~=1 then p.Transparency=1 end
end)
end
end
end
local function attach(m,acc)
local hd=acc:FindFirstChild("Handle")
if not hd or not hd:IsA("BasePart") then return end
hd.Anchored=false hd.CanCollide=false hd.CanTouch=false hd.CanQuery=false hd.Massless=true
local ha,ma
for _,a in ipairs(hd:GetChildren()) do
if a:IsA("Attachment") then
for _,d in ipairs(m:GetDescendants()) do
if d:IsA("Attachment") and d.Name==a.Name and not d:IsDescendantOf(acc) then ha,ma=a,d break end
end
end
if ma then break end
end
local w=Instance.new("Weld")
w.Name="AccessoryWeld"
if ma then
w.Part0=ma.Parent w.Part1=hd w.C0=ma.CFrame w.C1=ha.CFrame
else
local hh=m:FindFirstChild("Head")
if not hh then return end
w.Part0=hh w.Part1=hd w.C0=CFrame.new(0,hh.Size.Y/2,0)
end
acc.Parent=m
w.Parent=hd
end
local function extras(m)
for _,id in ipairs(EXTRA) do
local ok,o=pcall(function() return game:GetObjects(R..id) end)
if ok and o then
for _,x in ipairs(o) do
local l={x}
for _,d in ipairs(x:GetDescendants()) do l[#l+1]=d end
for _,i in ipairs(l) do
if i:IsA("Accessory") then attach(m,i:Clone())
elseif i:IsA("Shirt") or i:IsA("Pants") or i:IsA("ShirtGraphic") then
local old=m:FindFirstChildOfClass(i.ClassName)
if old then old:Destroy() end
i:Clone().Parent=m
end
end
end
else say("could not load "..id) end
end
end
local function animate(m,ch,hum,ids,alt)
local vh=m:FindFirstChildOfClass("Humanoid") or m:FindFirstChildOfClass("AnimationController")
if not vh then vh=Instance.new("AnimationController") vh.Parent=m end
local root=ch:FindFirstChild("HumanoidRootPart")
if not vh or not root then return end
local an=vh:FindFirstChildOfClass("Animator")
if not an then an=Instance.new("Animator") an.Parent=vh end
local tr,n={},0
local src={}
for _,k in ipairs(KEYS) do
local cl={ids[k],alt and alt[k]}
for j=1,2 do
local c=cl[j]
if c then
local ok,t=pcall(function() return an:LoadAnimation(pick(c,k)) end)
if ok and t then
local w=0
while t.Length==0 and w<1.5 do task.wait(0.1) w=w+0.1 end
if t.Length>0 then
if LOOP[k] then t.Looped=true end
pcall(function() t.Priority=Enum.AnimationPriority.Action4 end)
tr[k]=t
src[#src+1]=k..(j==1 and "" or "*")
n=n+1
break
else t:Destroy() end
end
end
end
end
say("playing: "..table.concat(src," ").." (* = pack)",true)
if n==0 then
local rm={}
for _,x in ipairs(ch:GetDescendants()) do
if x:IsA("Motor6D") and not x:IsDescendantOf(m) then rm[x.Name]=x end
end
local ln={}
for _,x in ipairs(m:GetDescendants()) do
if x:IsA("Motor6D") and rm[x.Name] then ln[#ln+1]={x,rm[x.Name]} end
end
local c
c=RS.RenderStepped:Connect(function()
if not m.Parent then c:Disconnect() return end
for _,l in ipairs(ln) do l[1].Transform=l[2].Transform end
end)
say("no pack animations, using your default ones",true)
return
end
local function res(w)
for _,k in ipairs(FB[w]) do
if tr[k] then return k end
end
end
local cur,jt,c=nil,0,nil
c=RS.Heartbeat:Connect(function()
if not m.Parent or not root.Parent then
c:Disconnect()
for _,t in pairs(tr) do t:Stop(0) end
return
end
local s=hum:GetState()
local v=root.AssemblyLinearVelocity
local sp=Vector3.new(v.X,0,v.Z).Magnitude
local w
if s==Enum.HumanoidStateType.Jumping then jt=os.clock() w="jump"
elseif s==Enum.HumanoidStateType.Freefall then w=(os.clock()-jt<0.5) and "jump" or "fall"
elseif s==Enum.HumanoidStateType.Climbing then w="climb"
elseif s==Enum.HumanoidStateType.Swimming then w="swim"
elseif sp>1 then w=(sp<SPEED*0.55) and "walk" or "run"
else w="idle" end
local k=res(w)
if k~=cur then
if cur and tr[cur] then tr[cur]:Stop(0.15) end
cur=k
if k then tr[k]:Play(0.15) end
end
if (k=="walk" or k=="run") and tr[k] then tr[k]:AdjustSpeed(math.clamp(sp/14.5,0.5,1.6)*ANIMSPEED) end
end)
end
local function apply(ch,ids)
local hum=ch:WaitForChild("Humanoid",10)
ch:WaitForChild("HumanoidRootPart",10)
if not hum or hum.RigType~=Enum.HumanoidRigType.R15 then say("R15 only",true) return end
local old=ch:FindFirstChild("64DudeVisual")
if old then old:Destroy() end
hum.WalkSpeed=SPEED
if G.wsc then G.wsc:Disconnect() end
G.wsc=hum:GetPropertyChangedSignal("WalkSpeed"):Connect(function()
if hum.WalkSpeed~=SPEED then hum.WalkSpeed=SPEED end
end)
local m,w
local alt=PKIDS
if MODEL then
local sm,all=mload()
if not sm then return end
if RIG then
m,w=rig(ch,sm,hum)
if not m then say("Mario rig failed",true) return end
local own,seen=kfs(all)
ids=own
alt=nil
say(("Mario anims: "..table.concat(seen,", ")):sub(1,170),true)
else
m,w=visual(ch,Instance.new("HumanoidDescription"))
if not m then return end
if not skin(m,sm) then say("Mario skin failed",true) end
ids={}
for k,v in pairs(PUB) do
local a=Instance.new("Animation")
a.AnimationId=R..v
ids[k]=a
end
end
else
local d,sh=desc()
if not d then return end
m,w=visual(ch,d,sh,extras)
end
if not m then return end
ground(m,ch,hum,w)
hum:RemoveAccessories()
hide(ch)
animate(m,ch,hum,ids,alt)
say("outfit applied",true)
end

return {apply=apply,animIds=animIds,off=function()
if G.wsc then G.wsc:Disconnect() G.wsc=nil end
local c=lp.Character
local v=c and c:FindFirstChild("64DudeVisual")
if v then v:Destroy() end
end}
end

