local MPIDS={77786727620364,79081744770812,117830374930403,117513983410171,102933665532878,114119813149640,100993431785272}
local MPN={}
for k in pairs(MAP) do MPN[#MPN+1]=k end
table.sort(MPN)
local MPC={}
for i,k in ipairs(MPN) do MPC[k]=i end
G.mp={IDS=MPIDS,NAMES=MPN}
local mps={tr={},on={}}
local function mpTracks(hum)
if mps.hum~=hum then
mps.hum=hum
mps.tr={}
mps.on={}
local an=hum:FindFirstChildOfClass("Animator")
if not an then
an=Instance.new("Animator")
an.Parent=hum
end
for i,id in ipairs(MPIDS) do
local a=Instance.new("Animation")
a.AnimationId="rbxassetid://"..id
local ok,t=pcall(function() return an:LoadAnimation(a) end)
if ok and t then
pcall(function() t.Priority=Enum.AnimationPriority.Core t.Looped=true end)
mps.tr[i]=t
end
end
end
end
local function mpSetT(i,on)
local t=mps.tr[i]
if not t or mps.on[i]==on then return end
mps.on[i]=on
pcall(function() if on then t:Play(0,0.01,1) else t:Stop(0) end end)
end
G.mpSend=function(hum,name)
mps.name=name
if G.mpOn==false then return end
mpTracks(hum)
local code=name and MPC[name] or 0
mpSetT(1,true)
for b=0,5 do mpSetT(b+2,math.floor(code/2^b)%2==1) end
end
local function mpStop()
for i=1,7 do mpSetT(i,false) end
end
local MPR={}
local SNDN={single_jump="jump",double_rise="jump2",triple="jump3",long_jump="jump3",backflip="jump3",first_punch="punch",second_punch="punch",air_kick="punch",dive="punch",gp_land="pound",land3="land3",dying="death"}
local function mpRead(pl)
local c=pl.Character
local hm=c and c:FindFirstChildOfClass("Humanoid")
local an=hm and hm:FindFirstChildOfClass("Animator")
if not an then return false end
local ok,ts=pcall(function() return an:GetPlayingAnimationTracks() end)
if not ok or not ts then return false end
local set={}
for _,t in ipairs(ts) do
local id=tonumber(string.match(tostring(t.Animation and t.Animation.AnimationId or ""),"%d+"))
if id then set[id]=true end
end
if not set[MPIDS[1]] then return false end
local code=0
for b=0,5 do if set[MPIDS[b+2]] then code=code+2^b end end
return true,code,c,hm
end
local function mpAdd(pl,c,hm)
local rt=c:FindFirstChild("HumanoidRootPart")
if not rt or hm.RigType~=Enum.HumanoidRigType.R15 then return nil end
local o=c:FindFirstChild("Mario64")
if o then o:Destroy() end
local orig={}
for _,d in ipairs(c:GetDescendants()) do
if d:IsA("BasePart") or d:IsA("Decal") or d:IsA("Texture") then orig[d]=d.Transparency end
end
local V=makeVisual(c,hm,rt)
local r={pl=pl,c=c,hm=hm,rt=rt,V=V,orig=orig,code=0,cand=-1,candT=0,seen=os.clock(),stepT=0,lastHit=0,name="idle"}
MPR[pl]=r
pcall(function() IN.toast(pl.Name.." joined as Mario!") end)
return r
end
local function mpDrop(pl)
local r=MPR[pl]
if not r then return end
MPR[pl]=nil
pcall(function() r.V.model:Destroy() end)
for d,t in pairs(r.orig) do
pcall(function() if d.Parent then d.Transparency=t end end)
end
end
local function mpApply(r,code)
local name=MPN[code]
if not name then return end
r.name=name
local k=SNDN[name]
if k then pcall(sfx,r.rt,k,0.9) end
end
local LOCO={running=true,walking=true,slow_walk=true,hold_slow=true,hold_walk=true,hold_run=true}
local function mpFrame(r,dt,now)
if not r.rt.Parent or not r.V.model.Parent then return end
local name=r.name or "idle"
local v=r.rt.AssemblyLinearVelocity
local sp=math.sqrt(v.X*v.X+v.Z*v.Z)
local spd=1
if LOCO[name] then
spd=math.min(math.max(sp*160/(30*MH),4)/4,8)*ANIMSPEED
if name=="running" or name=="walking" then
if sp>1 and now-r.stepT>math.clamp(9/sp,0.22,0.6) then r.stepT=now pcall(sfx,r.rt,"step",0.35) end
end
end
r.V.play(name,spd)
r.V.pose(dt)
if name=="air_kick" and now-r.lastHit>1.4 then
local me=lp.Character
local mr=me and me:FindFirstChild("HumanoidRootPart")
if mr then
local d=mr.Position-r.rt.Position
local fl=Vector3.new(d.X,0,d.Z)
local fw=r.rt.CFrame.LookVector
if fl.Magnitude>0.01 and fl.Magnitude<8 and math.abs(d.Y)<7 and fw:Dot(fl.Unit)>0.5 then
r.lastHit=now
pcall(function() mr.AssemblyLinearVelocity=fw*115+Vector3.new(0,55,0) end)
local mh=me:FindFirstChildOfClass("Humanoid")
if mh then
pcall(function() mh.PlatformStand=true end)
task.delay(1.4,function() pcall(function() mh.PlatformStand=false end) end)
end
pcall(sfx,mr,"thud",1)
pcall(IN.toast,"KICKED!")
end
end
end
end
if G.mpc then G.mpc:Disconnect() end
local mpPoll,mpRef=0,0
G.mpc=RS.Heartbeat:Connect(function(dt)
local now=os.clock()
if now-mpPoll>0.06 then
mpPoll=now
local alive={}
if G.mpOn~=false then
for _,pl in ipairs(P:GetPlayers()) do
if pl~=lp then
alive[pl]=true
local present,code,c,hm=mpRead(pl)
local r=MPR[pl]
if present then
if r and (r.c~=c or not r.c.Parent) then mpDrop(pl) r=nil end
if not r then r=mpAdd(pl,c,hm) end
if r then
r.seen=now
if code==r.cand then
if now-r.candT>=0.1 and code~=r.code then r.code=code mpApply(r,code) end
else r.cand=code r.candT=now end
end
elseif r and now-r.seen>2 then mpDrop(pl) end
end
end
end
for pl,_ in pairs(MPR) do if not alive[pl] then mpDrop(pl) end end
end
for _,r in pairs(MPR) do mpFrame(r,dt,now) end
if now-mpRef>3 then
mpRef=now
if mps.hum and mps.hum.Parent and G.mpOn~=false then
mps.on={}
G.mpSend(mps.hum,mps.name)
end
end
end)
G.mpSet=function(on)
G.mpOn=on and true or false
if on then
if mps.hum then mps.on={} G.mpSend(mps.hum,mps.name) end
else
mpStop()
for pl,_ in pairs(MPR) do mpDrop(pl) end
end
end
